"use client";

import React, { useEffect, useState, useMemo } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { fetchAlbum, fetchAlbumMedia, Album, MediaItem, SearchFilters } from '@/lib/api';
import { Sidebar } from '@/components/Sidebar';
import { GalleryGrid } from '@/components/GalleryGrid';
import { ChatPanel } from '@/components/ChatPanel';
import { Sparkles, Folder, ArrowLeft, Trash2, Edit2, Share2, Tag } from 'lucide-react';

export default function AlbumDetailPage() {
    const params = useParams();
    const router = useRouter();
    const albumId = parseInt(params.id as string);

    const [album, setAlbum] = useState<Album | null>(null);
    const [media, setMedia] = useState<MediaItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedItem, setSelectedItem] = useState<MediaItem | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    useEffect(() => {
        if (!albumId) return;

        Promise.all([
            fetchAlbum(albumId),
            fetchAlbumMedia(albumId)
        ]).then(([albumData, mediaData]) => {
            setAlbum(albumData);
            setMedia(mediaData);
        }).catch(err => {
            console.error('Failed to load album data:', err);
        }).finally(() => {
            setLoading(false);
        });
    }, [albumId]);

    const queryInfo = useMemo(() => {
        if (!album?.query_json) return null;
        try {
            return JSON.parse(album.query_json) as { query: string, filters: SearchFilters };
        } catch {
            return null;
        }
    }, [album]);

    if (loading) {
        return (
            <div className="flex items-center justify-center h-screen bg-zinc-950 text-zinc-500">
                <div className="animate-pulse flex flex-col items-center">
                    <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                    Loading Album...
                </div>
            </div>
        );
    }

    if (!album) {
        return (
            <div className="flex items-center justify-center h-screen bg-zinc-950 text-zinc-500">
                <div className="text-center">
                    <h1 className="text-2xl font-bold text-white mb-4">Album not found</h1>
                    <button onClick={() => router.push('/albums')} className="text-blue-500 hover:underline">
                        Back to Albums
                    </button>
                </div>
            </div>
        );
    }

    return (
        <main className="flex h-screen w-full bg-zinc-950 overflow-hidden font-sans">
            <Sidebar
                isOpen={isSidebarOpen}
                onClose={() => setIsSidebarOpen(false)}
            />

            <div className="flex-1 h-full relative border-r border-zinc-800 flex flex-col">
                <div className="p-8 pb-4 bg-zinc-950/50 backdrop-blur-sm sticky top-0 z-20">
                    <button
                        onClick={() => router.push('/albums')}
                        className="flex items-center gap-2 text-zinc-500 hover:text-white transition-colors mb-6 group text-sm font-medium"
                    >
                        <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                        Back to Albums
                    </button>

                    <div className="flex items-end justify-between">
                        <div>
                            <div className="flex items-center gap-3 mb-2">
                                {album.is_dynamic ? (
                                    <Sparkles className="w-6 h-6 text-blue-500" />
                                ) : (
                                    <Folder className="w-6 h-6 text-zinc-600" />
                                )}
                                <h1 className="text-4xl font-black text-white tracking-tight">{album.name}</h1>
                            </div>
                            <div className="flex items-center gap-4 text-zinc-500 text-sm font-medium">
                                <span>{media.length} {media.length === 1 ? 'item' : 'items'}</span>
                                <span className="w-1.5 h-1.5 rounded-full bg-zinc-800" />
                                <span>Created {new Date(album.created_at).toLocaleDateString()}</span>
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                            <button className="p-2.5 bg-zinc-900 border border-zinc-800 text-zinc-400 hover:text-white hover:bg-zinc-800 rounded-xl transition-all active:scale-95 shadow-lg">
                                <Share2 className="w-5 h-5" />
                            </button>
                            <button className="p-2.5 bg-zinc-900 border border-zinc-800 text-zinc-400 hover:text-white hover:bg-zinc-800 rounded-xl transition-all active:scale-95 shadow-lg">
                                <Edit2 className="w-5 h-5" />
                            </button>
                            <button className="p-2.5 bg-zinc-900 border border-zinc-800 text-zinc-400 hover:text-red-500 hover:bg-red-500/10 rounded-xl transition-all active:scale-95 shadow-lg">
                                <Trash2 className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    {album.is_dynamic && queryInfo && (
                        <div className="mt-8 p-4 bg-zinc-900/50 border border-zinc-800/50 rounded-2xl flex flex-col gap-3">
                            <div className="flex items-center gap-2">
                                <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Dynamic Query</span>
                                <div className="h-px flex-1 bg-zinc-800" />
                            </div>
                            <div className="flex items-center gap-4">
                                <span className="text-zinc-300 italic text-sm">"{queryInfo.query}"</span>
                                {Object.values(queryInfo.filters || {}).some(v => Array.isArray(v) ? v.length > 0 : !!v) && (
                                    <div className="flex flex-wrap gap-1.5 border-l border-zinc-800 pl-4">
                                        {Object.entries(queryInfo.filters || {}).flatMap(([key, val]) => (
                                            Array.isArray(val) ? val.map(v => ({ key, val: v })) : [{ key, val }]
                                        )).filter(f => !!f.val).map((filter, i) => (
                                            <div key={i} className="px-2 py-0.5 bg-zinc-950 border border-zinc-800 text-zinc-500 text-[10px] rounded-full flex items-center gap-1.5">
                                                <Tag className="w-2.5 h-2.5" />
                                                <span className="text-zinc-400 font-semibold uppercase">{filter.key}:</span>
                                                <span className="text-blue-400">{filter.val}</span>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {!album.is_dynamic && (
                        <div className="mt-6 flex items-center justify-between p-1 bg-zinc-900 border border-zinc-800 rounded-2xl">
                            <div className="px-4 text-xs font-bold text-zinc-500 uppercase tracking-wider">
                                Static Collection
                            </div>
                            <button className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-white text-xs font-bold rounded-xl transition-all active:scale-95 border border-zinc-700/50">
                                Add Items
                            </button>
                        </div>
                    )}
                </div>

                <div className="flex-1 min-h-0 bg-zinc-950">
                    <GalleryGrid
                        media={media}
                        onSelect={setSelectedItem}
                        hasMore={false}
                    />
                </div>
            </div>

            {selectedItem && (
                <ChatPanel
                    item={selectedItem}
                    onClose={() => setSelectedItem(null)}
                />
            )}
        </main>
    );
}

"use client";

import React, { useState } from 'react';
import { createAlbum, SearchFilters } from '@/lib/api';
import { useRouter } from 'next/navigation';

interface SaveAlbumModalProps {
    isOpen: boolean;
    onClose: () => void;
    currentQuery: string;
    currentFilters: SearchFilters;
}

export default function SaveAlbumModal({ isOpen, onClose, currentQuery, currentFilters }: SaveAlbumModalProps) {
    const [albumName, setAlbumName] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const router = useRouter();

    if (!isOpen) return null;

    const handleSave = async () => {
        if (!albumName.trim()) {
            setError('Please enter an album name');
            return;
        }

        setIsSubmitting(true);
        setError(null);

        try {
            const queryJson = JSON.stringify({
                query: currentQuery,
                filters: currentFilters,
                top_k: 100 // Reasonable default for dynamic albums
            });

            const albumId = await createAlbum(albumName, true, queryJson);
            onClose();
            router.push(`/albums/${albumId}`);
        } catch (err) {
            console.error('Failed to save album:', err);
            setError('Failed to save album. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="w-full max-w-md bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                <div className="p-6">
                    <h2 className="text-xl font-semibold text-white mb-2">Save as Smart Album</h2>
                    <p className="text-zinc-400 text-sm mb-6">
                        Smart albums automatically update whenever new files match your search criteria.
                    </p>

                    <div className="space-y-4">
                        <div>
                            <label htmlFor="albumName" className="block text-sm font-medium text-zinc-300 mb-1.5">
                                Album Name
                            </label>
                            <input
                                id="albumName"
                                type="text"
                                value={albumName}
                                onChange={(e) => setAlbumName(e.target.value)}
                                placeholder="e.g., My Favorite Landscapes"
                                className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-2.5 text-white placeholder-zinc-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
                                autoFocus
                            />
                        </div>

                        {error && (
                            <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400 text-sm">
                                {error}
                            </div>
                        )}

                        <div className="bg-zinc-800/30 rounded-xl p-4 border border-zinc-800/50">
                            <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-2">Query Preview</h3>
                            <div className="text-sm text-zinc-300 italic truncate">"{currentQuery}"</div>
                            {(currentFilters.tags?.length || currentFilters.character_tags?.length || currentFilters.series_tags?.length) && (
                                <div className="mt-2 flex flex-wrap gap-1.5">
                                    {[...(currentFilters.tags || []), ...(currentFilters.character_tags || []), ...(currentFilters.series_tags || [])].map((filter, i) => (
                                        <span key={i} className="px-2 py-0.5 bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[10px] rounded-full">
                                            {filter}
                                        </span>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className="flex items-center justify-end gap-3 p-6 bg-zinc-950/50 border-t border-zinc-800">
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-zinc-400 hover:text-white transition-colors"
                        disabled={isSubmitting}
                    >
                        Cancel
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={isSubmitting || !albumName.trim()}
                        className="px-6 py-2 bg-blue-600 hover:bg-blue-500 disabled:bg-zinc-800 disabled:text-zinc-500 text-white font-medium rounded-xl transition-all shadow-lg shadow-blue-600/20 flex items-center gap-2"
                    >
                        {isSubmitting && (
                            <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                            </svg>
                        )}
                        Save Album
                    </button>
                </div>
            </div>
        </div>
    );
}
